// UNiagaraScript::GetScriptData falls back to the exposed version for unknown GUIDs; only accept listed versions.
template<typename ScriptType> static auto ExactScriptData(ScriptType* Script,const FGuid& Version) -> decltype(Script->GetScriptData(Version))
{
 if(!Script) return nullptr;
 for(const auto& Available:Script->GetAllAvailableVersions()) if(Available.VersionGuid==Version) return Script->GetScriptData(Version);
 return nullptr;
}

// Function calls to unversioned scripts store an empty selected version, which resolves to the exposed version.
static bool MatchesSelectedVersion(const FGuid& Selected,const UNiagaraScript* Script,const FGuid& Requested)
{
 return Selected==Requested || (!Selected.IsValid() && IsValid(Script) && !Script->IsVersioningEnabled() && Script->GetExposedVersion().VersionGuid==Requested);
}

static bool IsUnsignedNumericProperty(const FNumericProperty* Property)
{
 return CastField<FByteProperty>(Property) || CastField<FUInt16Property>(Property) || CastField<FUInt32Property>(Property) || CastField<FUInt64Property>(Property);
}
