TArray<TObjectPtr<UNiagaraValidationRule>>& OwnedValidationRules(UObject* Owner)
{
 if(auto* Effect=Cast<UNiagaraEffectType>(Owner)) return Effect->ValidationRules;
 if(auto* RuleSet=Cast<UNiagaraValidationRuleSet>(Owner)) return RuleSet->ValidationRules;
 throw std::runtime_error("Effect type or reusable validation rule set owner required");
}

// These MinimalAPI getters are not exported by the installed engine.
UObject* InputReference(const UNiagaraNodeInput* Input, const TCHAR* Name)
{
 const auto* Property=FindFProperty<FObjectPropertyBase>(Input->GetClass(),Name);
 if(!Property) throw std::runtime_error("Native Niagara input reference property unavailable");
 return Property->GetObjectPropertyValue_InContainer(Input);
}

template<typename TWriter>
void WriteInputStoredValue(TWriter& J,const FNiagaraVariable& Variable)
{
 const auto& Type=Variable.GetType(); const int32 Allocated=Variable.GetAllocatedSizeInBytes();
 const uint8* Data=(!Type.IsDataInterface() && !Type.IsUObject() && Type.GetSize()>0 && Allocated==Type.GetSize())?Variable.GetData():nullptr;
 J->WriteObjectStart(TEXT("stored_input_value")); J->WriteValue(TEXT("allocated_bytes"),Allocated); J->WriteValue(TEXT("has_exact_value_data"),Data!=nullptr);
 if(Data && Type==FNiagaraTypeDefinition::GetFloatDef() && Type.GetSize()==sizeof(float)) { float Value; FMemory::Memcpy(&Value,Data,sizeof(Value)); J->WriteValue(TEXT("value_kind"),TEXT("float")); if(FMath::IsFinite(Value)) J->WriteValue(TEXT("value"),Value); else J->WriteNull(TEXT("value")); }
 else if(Data && Type==FNiagaraTypeDefinition::GetIntDef() && Type.GetSize()==sizeof(int32)) { int32 Value; FMemory::Memcpy(&Value,Data,sizeof(Value)); J->WriteValue(TEXT("value_kind"),TEXT("int")); J->WriteValue(TEXT("value"),Value); }
 else if(Data && Type==FNiagaraTypeDefinition::GetBoolDef() && Type.GetSize()==sizeof(FNiagaraBool)) { FNiagaraBool Value; FMemory::Memcpy(&Value,Data,sizeof(Value)); J->WriteValue(TEXT("value_kind"),TEXT("bool")); J->WriteValue(TEXT("value"),Value.GetValue()); }
 else if(Data && Type==FNiagaraTypeDefinition::GetVec3Def() && Type.GetSize()==sizeof(FVector3f)) { FVector3f Value; FMemory::Memcpy(&Value,Data,sizeof(Value)); J->WriteValue(TEXT("value_kind"),TEXT("vector3")); J->WriteObjectStart(TEXT("value")); if(FMath::IsFinite(Value.X)) J->WriteValue(TEXT("x"),Value.X); else J->WriteNull(TEXT("x")); if(FMath::IsFinite(Value.Y)) J->WriteValue(TEXT("y"),Value.Y); else J->WriteNull(TEXT("y")); if(FMath::IsFinite(Value.Z)) J->WriteValue(TEXT("z"),Value.Z); else J->WriteNull(TEXT("z")); J->WriteObjectEnd(); }
 else if(Data && Type==FNiagaraTypeDefinition::GetColorDef() && Type.GetSize()==sizeof(FLinearColor)) { FLinearColor Value; FMemory::Memcpy(&Value,Data,sizeof(Value)); J->WriteValue(TEXT("value_kind"),TEXT("color")); J->WriteObjectStart(TEXT("value")); const float Values[]={Value.R,Value.G,Value.B,Value.A}; const TCHAR* Keys[]={TEXT("r"),TEXT("g"),TEXT("b"),TEXT("a")}; for(int32 C=0;C<4;++C) { if(FMath::IsFinite(Values[C])) J->WriteValue(Keys[C],Values[C]); else J->WriteNull(Keys[C]); } J->WriteObjectEnd(); }
 else J->WriteValue(TEXT("value_kind"),TEXT("not_exported"));
 J->WriteObjectEnd();
}
template<typename TWriter>
void WriteEmitterSimulationSettings(TWriter& J, const FVersionedNiagaraEmitterData& Data)
{
 J->WriteObjectStart(TEXT("simulation_settings"));
 J->WriteValue(TEXT("local_space"),Data.bLocalSpace); J->WriteValue(TEXT("determinism"),Data.bDeterminism); J->WriteValue(TEXT("random_seed"),Data.RandomSeed);
 J->WriteValue(TEXT("requires_persistent_ids"),Data.bRequiresPersistentIDs!=0);
 J->WriteValue(TEXT("interpolated_spawn_mode"),static_cast<int32>(Data.InterpolatedSpawnMode));
 J->WriteValue(TEXT("interpolated_spawn_mode_name"),StaticEnum<ENiagaraInterpolatedSpawnMode>()->GetNameStringByValue(static_cast<int64>(Data.InterpolatedSpawnMode)));
 J->WriteValue(TEXT("bounds_mode"),static_cast<int32>(Data.CalculateBoundsMode));
 J->WriteValue(TEXT("bounds_mode_name"),StaticEnum<ENiagaraEmitterCalculateBoundMode>()->GetNameStringByValue(static_cast<int64>(Data.CalculateBoundsMode)));
 J->WriteValue(TEXT("allocation_mode"),static_cast<int32>(Data.AllocationMode));
 J->WriteValue(TEXT("allocation_mode_name"),StaticEnum<EParticleAllocationMode>()->GetNameStringByValue(static_cast<int64>(Data.AllocationMode)));
 J->WriteValue(TEXT("preallocation_count"),Data.PreAllocationCount); J->WriteValue(TEXT("max_gpu_particles_spawn_per_frame"),Data.MaxGPUParticlesSpawnPerFrame);
 const auto& Bounds=Data.FixedBounds;
 const bool Finite=FMath::IsFinite(Bounds.Min.X) && FMath::IsFinite(Bounds.Min.Y) && FMath::IsFinite(Bounds.Min.Z) && FMath::IsFinite(Bounds.Max.X) && FMath::IsFinite(Bounds.Max.Y) && FMath::IsFinite(Bounds.Max.Z);
 J->WriteObjectStart(TEXT("authored_fixed_bounds")); J->WriteValue(TEXT("valid"),Bounds.IsValid!=0); J->WriteValue(TEXT("finite"),Finite);
 if(Finite) { J->WriteArrayStart(TEXT("min")); J->WriteValue(Bounds.Min.X); J->WriteValue(Bounds.Min.Y); J->WriteValue(Bounds.Min.Z); J->WriteArrayEnd(); J->WriteArrayStart(TEXT("max")); J->WriteValue(Bounds.Max.X); J->WriteValue(Bounds.Max.Y); J->WriteValue(Bounds.Max.Z); J->WriteArrayEnd(); }
 J->WriteObjectEnd(); J->WriteObjectEnd();
}
template<typename TWriter>
void WriteScriptCompileSnapshot(TWriter& J, const UNiagaraScript* Script)
{
 J->WriteValue(TEXT("object_path"),GetPathNameSafe(Script)); J->WriteValue(TEXT("valid"),IsValid(Script));
  if(IsValid(Script))
  {
   J->WriteValue(TEXT("usage"),static_cast<int32>(Script->GetUsage())); J->WriteValue(TEXT("usage_name"),StaticEnum<ENiagaraScriptUsage>()->GetNameStringByValue(static_cast<int64>(Script->GetUsage()))); J->WriteValue(TEXT("usage_id"),Script->GetUsageId().ToString(EGuidFormats::DigitsWithHyphens));
   const auto Status=Script->GetLastCompileStatus();
   J->WriteValue(TEXT("last_compile_status"),static_cast<int32>(Status)); J->WriteValue(TEXT("last_compile_status_name"),StaticEnum<ENiagaraScriptCompileStatus>()->GetNameStringByValue(static_cast<int64>(Status)));
   J->WriteValue(TEXT("compile_error"),Status==ENiagaraScriptCompileStatus::NCS_Error); J->WriteValue(TEXT("compile_dirty"),Status==ENiagaraScriptCompileStatus::NCS_Dirty);
   J->WriteValue(TEXT("compile_has_warnings"),Status==ENiagaraScriptCompileStatus::NCS_UpToDateWithWarnings || Status==ENiagaraScriptCompileStatus::NCS_ComputeUpToDateWithWarnings);
   J->WriteValue(TEXT("cpu_compilation_pending"),Script->IsScriptCompilationPending(false)); J->WriteValue(TEXT("gpu_compilation_pending"),Script->IsScriptCompilationPending(true));
  }
}
template<typename TWriter>
void WriteEmitterScriptSnapshots(TWriter& J, const FVersionedNiagaraEmitterData& Data)
{
 const UNiagaraScript* Scripts[]={Data.EmitterSpawnScriptProps.Script.Get(),Data.EmitterUpdateScriptProps.Script.Get(),Data.SpawnScriptProps.Script.Get(),Data.UpdateScriptProps.Script.Get()};
 const TCHAR* Roles[]={TEXT("emitter_spawn"),TEXT("emitter_update"),TEXT("particle_spawn"),TEXT("particle_update")};
 J->WriteArrayStart(TEXT("scripts"));
 for(int32 I=0;I<4;++I)
 {
  const auto* Script=Scripts[I]; J->WriteObjectStart(); J->WriteValue(TEXT("role"),Roles[I]);
  WriteScriptCompileSnapshot(J,Script);
  J->WriteObjectEnd();
 }
 J->WriteArrayEnd();
 const auto& Events=Data.EventHandlerScriptProps;
 J->WriteValue(TEXT("event_handler_count"),Events.Num()); J->WriteValue(TEXT("event_handlers_truncated"),Events.Num()>64); J->WriteArrayStart(TEXT("event_handlers"));
 for(int32 I=0;I<FMath::Min(Events.Num(),64);++I)
 {
  const auto& Event=Events[I]; J->WriteObjectStart(); J->WriteValue(TEXT("index"),I);
  WriteScriptCompileSnapshot(J,Event.Script.Get());
  J->WriteValue(TEXT("execution_mode"),static_cast<int32>(Event.ExecutionMode)); J->WriteValue(TEXT("execution_mode_name"),StaticEnum<EScriptExecutionMode>()->GetNameStringByValue(static_cast<int64>(Event.ExecutionMode)));
  J->WriteValue(TEXT("source_emitter_id"),Event.SourceEmitterID.ToString(EGuidFormats::DigitsWithHyphens)); J->WriteValue(TEXT("source_is_self"),!Event.SourceEmitterID.IsValid()); J->WriteValue(TEXT("source_event_name"),Event.SourceEventName.ToString());
  J->WriteValue(TEXT("spawn_number"),static_cast<int64>(Event.SpawnNumber)); J->WriteValue(TEXT("max_events_per_frame"),static_cast<int64>(Event.MaxEventsPerFrame)); J->WriteValue(TEXT("random_spawn_number"),Event.bRandomSpawnNumber); J->WriteValue(TEXT("min_spawn_number"),static_cast<int64>(Event.MinSpawnNumber)); J->WriteValue(TEXT("update_attribute_initial_values"),Event.UpdateAttributeInitialValues);
  J->WriteObjectEnd();
 }
 J->WriteArrayEnd();

 const auto& Stages=Data.GetSimulationStages();
 J->WriteValue(TEXT("simulation_stage_count"),Stages.Num()); J->WriteValue(TEXT("simulation_stages_truncated"),Stages.Num()>64); J->WriteArrayStart(TEXT("simulation_stages"));
 for(int32 I=0;I<FMath::Min(Stages.Num(),64);++I)
 {
  const auto* Stage=Stages[I]; J->WriteObjectStart(); J->WriteValue(TEXT("index"),I); J->WriteValue(TEXT("object_path"),GetPathNameSafe(Stage)); J->WriteValue(TEXT("valid"),IsValid(Stage));
  if(IsValid(Stage))
  {
   J->WriteValue(TEXT("class_path"),Stage->GetClass()->GetPathName()); J->WriteValue(TEXT("name"),Stage->SimulationStageName.ToString()); J->WriteValue(TEXT("enabled"),Stage->bEnabled!=0); J->WriteValue(TEXT("outer_emitter_version"),Stage->OuterEmitterVersion.ToString(EGuidFormats::DigitsWithHyphens));
   J->WriteObjectStart(TEXT("script")); WriteScriptCompileSnapshot(J,Stage->Script.Get()); J->WriteObjectEnd();
   int32 Count=0; J->WriteArrayStart(TEXT("editable_fields"));
   for(TFieldIterator<FProperty> It(Stage->GetClass());It;++It)
   {
    if(!It->HasAnyPropertyFlags(CPF_Edit) || It->HasAnyPropertyFlags(CPF_Transient|CPF_Deprecated)) continue; if(Count++>=64) continue;
    FString Value; It->ExportTextItem_Direct(Value,It->ContainerPtrToValuePtr<void>(Stage),nullptr,const_cast<UNiagaraSimulationStageBase*>(Stage),PPF_None);
    J->WriteObjectStart(); J->WriteValue(TEXT("name"),It->GetName()); J->WriteValue(TEXT("type"),It->GetCPPType()); J->WriteValue(TEXT("edit_const"),It->HasAnyPropertyFlags(CPF_EditConst)); J->WriteValue(TEXT("value"),Value.Left(4096)); J->WriteValue(TEXT("value_truncated"),Value.Len()>4096);
    const auto* EnumField=CastField<FEnumProperty>(*It); const auto* Byte=CastField<FByteProperty>(*It); const UEnum* Enum=EnumField?EnumField->GetEnum():(Byte?Byte->Enum.Get():nullptr);
    if(Enum)
    {
     J->WriteValue(TEXT("enum_path"),Enum->GetPathName()); J->WriteArrayStart(TEXT("enum_choices")); int32 Choices=0;
     for(int32 E=0;E<Enum->NumEnums();++E)
     {
      if(Enum->HasMetaData(TEXT("Hidden"),E) || Enum->GetNameStringByIndex(E).EndsWith(TEXT("_MAX"))) continue; if(Choices++>=128) continue;
      J->WriteObjectStart(); J->WriteValue(TEXT("name"),Enum->GetNameStringByIndex(E)); J->WriteValue(TEXT("qualified_name"),Enum->GetNameByIndex(E).ToString()); J->WriteValue(TEXT("value_text"),LexToString(Enum->GetValueByIndex(E))); J->WriteObjectEnd();
     }
     J->WriteArrayEnd(); J->WriteValue(TEXT("enum_choices_truncated"),Choices>128);
    }
    for(const FName Key:{FName(TEXT("ClampMin")),FName(TEXT("ClampMax")),FName(TEXT("EditCondition")),FName(TEXT("DisplayName"))}) if(It->HasMetaData(Key)) J->WriteValue(Key.ToString(),It->GetMetaData(Key));
    J->WriteObjectEnd();
   }
   J->WriteArrayEnd(); J->WriteValue(TEXT("editable_field_count"),Count); J->WriteValue(TEXT("editable_fields_truncated"),Count>64);
   J->WriteArrayStart(TEXT("integer_default_bindings"));
   for(const FName Name:{FName(TEXT("NumIterations")),FName(TEXT("ElementCountX")),FName(TEXT("ElementCountY")),FName(TEXT("ElementCountZ")),FName(TEXT("OverrideGpuDispatchNumThreadsX")),FName(TEXT("OverrideGpuDispatchNumThreadsY")),FName(TEXT("OverrideGpuDispatchNumThreadsZ"))})
   {
    const auto* Field=FindFProperty<FStructProperty>(Stage->GetClass(),Name);
    if(!Field || Field->Struct!=FNiagaraParameterBindingWithValue::StaticStruct()) continue;
    const auto* Binding=Field->ContainerPtrToValuePtr<FNiagaraParameterBindingWithValue>(Stage); const auto Bytes=Binding->GetDefaultValueArray();
    J->WriteObjectStart(); J->WriteValue(TEXT("field"),Name.ToString()); J->WriteValue(TEXT("resolved_parameter"),Binding->ResolvedParameter.GetName().ToString()); J->WriteValue(TEXT("aliased_parameter"),Binding->AliasedParameter.GetName().ToString()); J->WriteValue(TEXT("type_name"),Binding->ResolvedParameter.GetType().GetName()); J->WriteValue(TEXT("default_size_bytes"),Bytes.Num());
    const bool Typed=Binding->ResolvedParameter.GetType()==FNiagaraTypeDefinition::GetIntDef() && Bytes.Num()==sizeof(int32); J->WriteValue(TEXT("int32_default_available"),Typed);
    if(Typed) { int32 Value; FMemory::Memcpy(&Value,Bytes.GetData(),sizeof(Value)); J->WriteValue(TEXT("default_value"),Value); } else J->WriteNull(TEXT("default_value"));
    J->WriteValue(TEXT("has_parameter_name"),!Binding->ResolvedParameter.GetName().IsNone()); J->WriteObjectEnd();
   }
   J->WriteArrayEnd();
  }
  J->WriteObjectEnd();
 }
 J->WriteArrayEnd();

}
