 if(!R.bDryRun && Changed) { FScopedTransaction Transaction(FText::FromString(TEXT("MCP Niagara Emitter Enabled"))); System->Modify(); System->GetEmitterHandles()[R.EmitterIndex].SetIsEnabled(R.bEnabled,*System,false); System->PostEditChange(); if(!System->GetEmitterHandles().IsValidIndex(R.EmitterIndex) || System->GetEmitterHandles()[R.EmitterIndex].GetId()!=Id || System->GetEmitterHandles()[R.EmitterIndex].GetIsEnabled()!=R.bEnabled) throw std::runtime_error("Native emitter enable readback mismatch; inspect undo transaction"); System->MarkPackageDirty(); }
