 const FString Before=GetPathNameSafe(System->GetEffectType()); const bool Changed=System->GetEffectType()!=Requested; bool Saved=false;
 if(!R.bDryRun && Changed) { FScopedTransaction Transaction(FText::FromString(TEXT("MCP Niagara Effect Type"))); System->Modify(); System->SetEffectType(Requested); System->PostEditChange(); if(System->GetEffectType()!=Requested) throw std::runtime_error("Native effect type readback mismatch; inspect undo transaction"); System->MarkPackageDirty(); }
