 FString Result; auto J=TJsonWriterFactory<>::Create(&Result); J->WriteObjectStart(); J->WriteValue(TEXT("asset_path"),R.AssetPath); J->WriteValue(TEXT("before_effect_type"),Before); J->WriteValue(TEXT("requested_effect_type"),R.SourceAssetPath); J->WriteValue(TEXT("would_change"),Changed); J->WriteValue(TEXT("dry_run"),R.bDryRun); J->WriteValue(TEXT("saved"),Saved); J->WriteValue(TEXT("scope"),TEXT("Native effect-type reference assignment/clear and scalability resolution; shared policy unchanged. Native update context may reinitialize live instances. No explicit compile/simulation/rendering or scalability behavior proof.")); J->WriteObjectEnd(); J->Close(); return Result;
