 auto Valid=[](const FVector& V) { return FMath::IsFinite(V.X) && FMath::IsFinite(V.Y) && FMath::IsFinite(V.Z) && V.GetAbsMax()<=1.e9; };
 if(!IsInGameThread() || !GEditor || GEditor->PlayWorld || !R.bConfirm || !R.AssetPath.StartsWith(TEXT("/Game/")) || R.AssetPath.Len()>1024 || R.AssetPath.Contains(TEXT(":")) || !FPackageName::IsValidObjectPath(R.AssetPath) || !Valid(R.BoundsMin) || !Valid(R.BoundsMax) || R.BoundsMin.X>R.BoundsMax.X || R.BoundsMin.Y>R.BoundsMax.Y || R.BoundsMin.Z>R.BoundsMax.Z) throw std::runtime_error("Fixed bounds require confirmed /Game/stopped PIE and finite bounded ordered corners");
