 if(!R.bDryRun && Changed) { FScopedTransaction Transaction(FText::FromString(TEXT("MCP Niagara Fixed Bounds"))); System->Modify(); System->SetFixedBounds(Requested); System->bFixedBounds=R.bEnabled; FPropertyChangedEvent Event(Property,EPropertyChangeType::ValueSet); System->PostEditChangeProperty(Event); if((System->bFixedBounds!=0)!=R.bEnabled || !Property->Struct->CompareScriptStruct(Value,&Requested,0)) throw std::runtime_error("Native fixed bounds readback mismatch; inspect undo transaction"); System->MarkPackageDirty(); }
