  Text(TEXT("category"),Data->Category); Text(TEXT("description"),Data->Description); Text(TEXT("keywords"),Data->Keywords); Text(TEXT("version_changes"),Data->VersionChangeDescription); Text(TEXT("deprecation_message"),Data->DeprecationMessage); Text(TEXT("experimental_message"),Data->ExperimentalMessage); Text(TEXT("note"),Data->NoteMessage);
  J->WriteValue(TEXT("deprecation_recommendation_path"),GetPathNameSafe(Data->DeprecationRecommendation.Get()));
  J->WriteValue(TEXT("provided_dependency_count"),Data->ProvidedDependencies.Num()); J->WriteValue(TEXT("provided_dependencies_truncated"),Data->ProvidedDependencies.Num()>128); J->WriteArrayStart(TEXT("provided_dependencies")); for(int32 D=0;D<FMath::Min(Data->ProvidedDependencies.Num(),128);++D) J->WriteValue(Data->ProvidedDependencies[D].ToString()); J->WriteArrayEnd(); J->WriteValue(TEXT("required_dependency_count"),Data->RequiredDependencies.Num());
  J->WriteValue(TEXT("required_dependencies_truncated"),Data->RequiredDependencies.Num()>128); J->WriteArrayStart(TEXT("required_dependencies"));
