 auto* Script=LoadObject<UNiagaraScript>(nullptr,*R.AssetPath); if(!IsValid(Script) || Script->HasAnyFlags(RF_Transient)) throw std::runtime_error("Persistent native script required"); auto* Data=ExactScriptData(Script,Version); if(!Data) throw std::runtime_error("Script version unavailable");
