FString NiagaraUtils::ResizeScriptCommentBox(const FNiagaraReq& R)
{
 if(!IsInGameThread() || !GEditor || GEditor->PlayWorld || !R.bConfirm || !R.AssetPath.StartsWith(TEXT("/Game/")) || R.AssetPath.IsEmpty() || R.AssetPath.Len()>1024 || R.AssetPath.Contains(TEXT(":")) || !FPackageName::IsValidObjectPath(R.AssetPath) || !FModuleManager::LoadModuleChecked<FAssetRegistryModule>(TEXT("AssetRegistry")).Get().GetAssetByObjectPath(FSoftObjectPath(R.AssetPath)).IsValid()) throw std::runtime_error("Registered bounded script asset path required");
 FGuid Version; if(R.VersionId.Len()>64 || !FGuid::Parse(R.VersionId,Version) || !Version.IsValid()) throw std::runtime_error("Explicit valid script version required");
 auto* Script=LoadObject<UNiagaraScript>(nullptr,*R.AssetPath); if(!IsValid(Script) || Script->HasAnyFlags(RF_Transient) || !ExactScriptData(Script,Version)) throw std::runtime_error("Persistent script and existing version required");
 auto* Source=Cast<UNiagaraScriptSource>(Script->GetSource(Version)); auto* Graph=IsValid(Source)?Source->NodeGraph.Get():nullptr;
 if(!IsValid(Graph) || !Graph->IsIn(Script) || Graph->Nodes.Num()>256 || R.NodePath.IsEmpty() || R.NodePath.Len()>2048 || R.NodeId.Len()>64 || R.NodeWidth<32 || R.NodeWidth>100000 || R.NodeHeight<32 || R.NodeHeight>100000) throw std::runtime_error("Owned bounded script graph/node identity and bounded coordinates required");
 FGuid Id; if(!FGuid::Parse(R.NodeId,Id) || !Id.IsValid()) throw std::runtime_error("Valid node GUID required"); UEdGraphNode* Node=nullptr; int32 Matches=0;
 for(const auto& Item:Graph->Nodes) if(IsValid(Item.Get()) && Item->NodeGuid==Id) { ++Matches; Node=Item.Get(); }
 if(Matches!=1 || !Node || Node->GetPathName()!=R.NodePath || Node->GetGraph()!=Graph) throw std::runtime_error("Unique current node GUID/path/graph identity required");
 auto* CommentClass=FindObject<UClass>(nullptr,TEXT("/Script/UnrealEd.EdGraphNode_Comment")); if(!CommentClass || !Node->IsA(CommentClass)) throw std::runtime_error("Native comment box node required");
 const int32 BeforeX=Node->NodeWidth,BeforeY=Node->NodeHeight; const bool Changed=BeforeX!=R.NodeWidth || BeforeY!=R.NodeHeight; bool Saved=false;
 if(!R.bDryRun && Changed)
 {
  FScopedTransaction Transaction(FText::FromString(TEXT("MCP Niagara Comment Box Size"))); Script->Modify(); Source->Modify(); Graph->Modify(); Node->SetFlags(RF_Transactional); Node->Modify(); Node->NodeWidth=R.NodeWidth; Node->NodeHeight=R.NodeHeight; Graph->NotifyGraphChanged();
  const auto* Current=Cast<UNiagaraScriptSource>(Script->GetSource(Version)); if(!IsValid(Current) || Current->NodeGraph.Get()!=Graph || !Graph->Nodes.Contains(Node) || Node->NodeGuid!=Id || Node->GetPathName()!=R.NodePath || Node->NodeWidth!=R.NodeWidth || Node->NodeHeight!=R.NodeHeight) throw std::runtime_error("Comment box size readback mismatch; inspect undo transaction"); Script->MarkPackageDirty();
 }
 if(!R.bDryRun && R.bSave) { Saved=GEditor->GetEditorSubsystem<UEditorAssetSubsystem>()->SaveLoadedAsset(Script,false); if(!Saved) throw std::runtime_error("Comment box resized but script save failed"); }
 FString Result; auto J=TJsonWriterFactory<>::Create(&Result); J->WriteObjectStart(); J->WriteValue(TEXT("asset_path"),R.AssetPath); J->WriteValue(TEXT("version_id"),R.VersionId); J->WriteValue(TEXT("node_id"),R.NodeId); J->WriteValue(TEXT("node_path"),R.NodePath); J->WriteValue(TEXT("before_width"),BeforeX); J->WriteValue(TEXT("before_height"),BeforeY); J->WriteValue(TEXT("requested_width"),R.NodeWidth); J->WriteValue(TEXT("requested_height"),R.NodeHeight); J->WriteValue(TEXT("would_change"),Changed); J->WriteValue(TEXT("dry_run"),R.bDryRun); J->WriteValue(TEXT("saved"),Saved); J->WriteValue(TEXT("scope"),TEXT("Authored comment box dimensions with native graph notification; versions sharing a graph share dimension changes. Native callbacks may schedule derived work. No explicit compile request/wait, simulation or rendering.")); J->WriteObjectEnd(); J->Close(); return Result;
}

FString NiagaraUtils::ValidateScriptGraph(const FNiagaraReq& R)
{
 if(!IsInGameThread() || R.AssetPath.IsEmpty() || R.AssetPath.Len()>1024 || R.AssetPath.Contains(TEXT(":")) || !FPackageName::IsValidObjectPath(R.AssetPath) || !FModuleManager::LoadModuleChecked<FAssetRegistryModule>(TEXT("AssetRegistry")).Get().GetAssetByObjectPath(FSoftObjectPath(R.AssetPath)).IsValid()) throw std::runtime_error("Registered bounded script asset path required");
 FGuid Version; if(R.VersionId.Len()>64 || !FGuid::Parse(R.VersionId,Version) || !Version.IsValid()) throw std::runtime_error("Explicit valid script version required");
 const auto* Script=LoadObject<UNiagaraScript>(nullptr,*R.AssetPath); if(!IsValid(Script) || Script->HasAnyFlags(RF_Transient) || !ExactScriptData(Script,Version)) throw std::runtime_error("Persistent script and existing version required");
 const auto* Source=Cast<UNiagaraScriptSource>(Script->GetSource(Version)); const auto* Graph=IsValid(Source)?Source->NodeGraph.Get():nullptr;
 if(!IsValid(Graph) || Graph->Nodes.Num()>256) throw std::runtime_error("Native graph with at most 256 nodes required");
 TSet<const UEdGraphNode*> Nodes; TSet<FGuid> NodeIds,PinIds; TSet<const UEdGraphPin*> Pins; int32 TotalPins=0,TotalLinks=0,IssueCount=0; FString Result; auto J=TJsonWriterFactory<>::Create(&Result); J->WriteObjectStart(); J->WriteValue(TEXT("asset_path"),R.AssetPath); J->WriteValue(TEXT("version_id"),R.VersionId); J->WriteArrayStart(TEXT("issues"));
 auto Issue=[&](const TCHAR* Code,const UEdGraphNode* Node,const UEdGraphPin* Pin) { if(IssueCount++>=256) return; J->WriteObjectStart(); J->WriteValue(TEXT("code"),Code); J->WriteValue(TEXT("node_path"),GetPathNameSafe(Node)); if(Pin) J->WriteValue(TEXT("pin_id"),Pin->PinId.ToString(EGuidFormats::DigitsWithHyphens)); J->WriteObjectEnd(); };
 for(const auto& Item:Graph->Nodes)
 {
  const auto* Node=Item.Get(); if(!IsValid(Node)) { Issue(TEXT("invalid_node"),nullptr,nullptr); continue; }
  if(Nodes.Contains(Node)) Issue(TEXT("duplicate_node_pointer"),Node,nullptr); Nodes.Add(Node); if(Node->GetGraph()!=Graph) Issue(TEXT("node_graph_mismatch"),Node,nullptr); if(!Node->NodeGuid.IsValid()) Issue(TEXT("invalid_node_guid"),Node,nullptr); else if(NodeIds.Contains(Node->NodeGuid)) Issue(TEXT("duplicate_node_guid"),Node,nullptr); NodeIds.Add(Node->NodeGuid);
  if(Node->Pins.Num()>64 || TotalPins+Node->Pins.Num()>4096) throw std::runtime_error("Validation exceeds 64 pins/node or 4096 total pin budget"); TotalPins+=Node->Pins.Num();
  for(const auto* Pin:Node->Pins) { if(!Pin) { Issue(TEXT("null_pin"),Node,nullptr); continue; } if(Pins.Contains(Pin)) Issue(TEXT("duplicate_pin_pointer"),Node,Pin); Pins.Add(Pin); if(Pin->GetOwningNode()!=Node) Issue(TEXT("pin_owner_mismatch"),Node,Pin); if(!Pin->PinId.IsValid()) Issue(TEXT("invalid_pin_guid"),Node,Pin); else if(PinIds.Contains(Pin->PinId)) Issue(TEXT("duplicate_pin_guid"),Node,Pin); PinIds.Add(Pin->PinId); if(Pin->bOrphanedPin) Issue(TEXT("orphaned_pin"),Node,Pin); }
 }
 TMap<FName,const UNiagaraNodeInput*> Inputs;
 for(const auto* Node:Nodes)
 {
  const auto* Input=Cast<UNiagaraNodeInput>(Node); if(!Input || Input->Usage!=ENiagaraInputNodeUsage::Parameter) continue;
  const FName Name=Input->Input.GetName(); if(Name.IsNone()) Issue(TEXT("input_name_none"),Node,nullptr);
  if(const auto* Existing=Inputs.Find(Name))
  {
   const auto* Other=*Existing;
   if(Other->Input.GetType()!=Input->Input.GetType()) Issue(TEXT("input_type_conflict"),Node,nullptr);
   if(Other->ExposureOptions.bExposed!=Input->ExposureOptions.bExposed || Other->ExposureOptions.bRequired!=Input->ExposureOptions.bRequired || Other->ExposureOptions.bHidden!=Input->ExposureOptions.bHidden || Other->ExposureOptions.bCanAutoBind!=Input->ExposureOptions.bCanAutoBind) Issue(TEXT("input_exposure_conflict"),Node,nullptr);
   if(Other->CallSortPriority!=Input->CallSortPriority) Issue(TEXT("input_priority_conflict"),Node,nullptr);
   if(InputReference(Other,TEXT("DataInterface"))!=InputReference(Input,TEXT("DataInterface")) || InputReference(Other,TEXT("ObjectAsset"))!=InputReference(Input,TEXT("ObjectAsset"))) Issue(TEXT("input_object_reference_conflict"),Node,nullptr);
  }
  else Inputs.Add(Name,Input);
  const auto& Type=Input->Input.GetType(); if(!Type.IsDataInterface() && !Type.IsUObject() && Input->Input.GetAllocatedSizeInBytes()!=Type.GetSize()) Issue(TEXT("input_value_allocation_mismatch"),Node,nullptr);
 }
 for(const auto* Pin:Pins)
 {
  if(Pin->LinkedTo.Num()>64 || TotalLinks+Pin->LinkedTo.Num()>16384) throw std::runtime_error("Validation exceeds link budget"); TotalLinks+=Pin->LinkedTo.Num(); TSet<const UEdGraphPin*> SeenLinks;
  for(const auto* Link:Pin->LinkedTo) { if(!Link) { Issue(TEXT("null_link"),Pin->GetOwningNode(),Pin); continue; } if(!Pins.Contains(Link)) { Issue(TEXT("external_or_unlisted_link"),Pin->GetOwningNode(),Pin); continue; } if(SeenLinks.Contains(Link)) Issue(TEXT("duplicate_link"),Pin->GetOwningNode(),Pin); SeenLinks.Add(Link); if(Link==Pin) Issue(TEXT("self_pin_link"),Pin->GetOwningNode(),Pin); if(Link->Direction==Pin->Direction) Issue(TEXT("same_direction_link"),Pin->GetOwningNode(),Pin); if(!Link->LinkedTo.Contains(const_cast<UEdGraphPin*>(Pin))) Issue(TEXT("asymmetric_link"),Pin->GetOwningNode(),Pin); }
 }
 J->WriteArrayEnd(); J->WriteValue(TEXT("issue_count"),IssueCount); J->WriteValue(TEXT("issues_truncated"),IssueCount>256); J->WriteValue(TEXT("structural_issues_found"),IssueCount>0); J->WriteValue(TEXT("nodes_checked"),Nodes.Num()); J->WriteValue(TEXT("pins_checked"),TotalPins); J->WriteValue(TEXT("directed_links_checked"),TotalLinks); J->WriteValue(TEXT("scope"),TEXT("Bounded authored structural diagnostics only; no schema type inference, reference recursion, compile or runtime validity proof. No mutation, compile request/wait, simulation or rendering.")); J->WriteObjectEnd(); J->Close(); return Result;
}

FString NiagaraUtils::DuplicateScriptNode(const FNiagaraReq& R)
{
 if(!IsInGameThread() || !GEditor || GEditor->PlayWorld || !R.bConfirm || !R.AssetPath.StartsWith(TEXT("/Game/")) || R.AssetPath.IsEmpty() || R.AssetPath.Len()>1024 || R.AssetPath.Contains(TEXT(":")) || !FPackageName::IsValidObjectPath(R.AssetPath) || !FModuleManager::LoadModuleChecked<FAssetRegistryModule>(TEXT("AssetRegistry")).Get().GetAssetByObjectPath(FSoftObjectPath(R.AssetPath)).IsValid()) throw std::runtime_error("Registered bounded script asset path required");
 FGuid Version; if(R.VersionId.Len()>64 || !FGuid::Parse(R.VersionId,Version) || !Version.IsValid()) throw std::runtime_error("Explicit valid script version required");
 auto* Script=LoadObject<UNiagaraScript>(nullptr,*R.AssetPath); if(!IsValid(Script) || Script->HasAnyFlags(RF_Transient) || !ExactScriptData(Script,Version)) throw std::runtime_error("Persistent script and existing version required");
 auto* Source=Cast<UNiagaraScriptSource>(Script->GetSource(Version)); auto* Graph=IsValid(Source)?Source->NodeGraph.Get():nullptr;
 if(!IsValid(Graph) || !Graph->IsIn(Script) || Graph->Nodes.Num()>256 || R.NodePath.IsEmpty() || R.NodePath.Len()>2048 || R.NodeId.Len()>64 || R.NodeX < -1000000 || R.NodeX>1000000 || R.NodeY < -1000000 || R.NodeY>1000000) throw std::runtime_error("Owned bounded script graph/node identity and bounded coordinates required");
 FGuid Id; if(!FGuid::Parse(R.NodeId,Id) || !Id.IsValid()) throw std::runtime_error("Valid node GUID required"); UEdGraphNode* Node=nullptr; int32 Matches=0;
 for(const auto& Item:Graph->Nodes) if(IsValid(Item.Get()) && Item->NodeGuid==Id) { ++Matches; Node=Item.Get(); }
 if(Matches!=1 || !Node || Node->GetPathName()!=R.NodePath || Node->GetGraph()!=Graph) throw std::runtime_error("Unique current node GUID/path/graph identity required");
 const FString ClassPath=Node->GetClass()->GetPathName(); if(!Node->CanDuplicateNode() || (ClassPath!=TEXT("/Script/NiagaraEditor.NiagaraNodeOp") && ClassPath!=TEXT("/Script/NiagaraEditor.NiagaraNodeReroute") && ClassPath!=TEXT("/Script/UnrealEd.EdGraphNode_Comment")) || Graph->Nodes.Num()>=256 || Node->Pins.Num()>64) throw std::runtime_error("Duplicable native operation/reroute/comment with available graph capacity required");
 const int32 BeforeCount=Graph->Nodes.Num(); UEdGraphNode* Created=nullptr; bool Saved=false;
 if(!R.bDryRun)
 {
  FScopedTransaction Transaction(FText::FromString(TEXT("MCP Niagara Duplicate Node"))); Script->Modify(); Source->Modify(); Graph->Modify(); Node->Modify(); const FName SourceName=Node->GetFName(); Node->PrepareForCopying(); TSet<UObject*> Export; Export.Add(Node); FString Text; FEdGraphUtilities::ExportNodesToText(Export,Text); if(Text.Len()>1048576 || !FEdGraphUtilities::CanImportNodesFromText(Graph,Text)) throw std::runtime_error("Node export exceeds bound or import rejected"); TSet<UEdGraphNode*> Imported; FEdGraphUtilities::ImportNodesFromText(Graph,Text,Imported); if(Imported.Num()!=1) throw std::runtime_error("Expected one imported node; inspect undo transaction");
  Created=*Imported.CreateConstIterator(); if(Node->GetFName()!=SourceName && IsValid(Created) && Created!=Node) { /* Text import renames the existing same-named source to make room; give the copy a fresh name and restore the source identity. */ Created->Rename(*MakeUniqueObjectName(Graph,Created->GetClass()).ToString(),nullptr,REN_DontCreateRedirectors); if(!Node->Rename(*SourceName.ToString(),nullptr,REN_DontCreateRedirectors|REN_Test) || !Node->Rename(*SourceName.ToString(),nullptr,REN_DontCreateRedirectors)) throw std::runtime_error("Source node name restoration failed; inspect undo transaction"); } Created->CreateNewGuid(); Created->NodePosX=R.NodeX; Created->NodePosY=R.NodeY; Graph->NotifyGraphChanged();
  const auto* Current=Cast<UNiagaraScriptSource>(Script->GetSource(Version)); if(!IsValid(Current) || Current->NodeGraph.Get()!=Graph || !IsValid(Created) || Created==Node || Created->GetClass()!=Node->GetClass() || !Graph->Nodes.Contains(Created) || Graph->Nodes.Num()!=BeforeCount+1 || !Created->NodeGuid.IsValid() || Created->NodeGuid==Id || Created->Pins.Num()>64 || Node->GetFName()!=SourceName) throw std::runtime_error("Duplicated node identity readback mismatch; inspect undo transaction");
  for(const auto* Pin:Created->Pins) if(!Pin || !Pin->LinkedTo.IsEmpty()) throw std::runtime_error("Duplicated single node must have valid unlinked pins; inspect undo transaction"); Script->MarkPackageDirty();
 }
 if(!R.bDryRun && R.bSave) { Saved=GEditor->GetEditorSubsystem<UEditorAssetSubsystem>()->SaveLoadedAsset(Script,false); if(!Saved) throw std::runtime_error("Node duplicated but save failed"); }
 FString Result; auto J=TJsonWriterFactory<>::Create(&Result); J->WriteObjectStart(); J->WriteValue(TEXT("asset_path"),R.AssetPath); J->WriteValue(TEXT("version_id"),R.VersionId); J->WriteValue(TEXT("source_node_id"),R.NodeId); J->WriteValue(TEXT("created"),IsValid(Created)); if(IsValid(Created)) { J->WriteValue(TEXT("node_id"),Created->NodeGuid.ToString(EGuidFormats::DigitsWithHyphens)); J->WriteValue(TEXT("node_path"),Created->GetPathName()); } J->WriteValue(TEXT("dry_run"),R.bDryRun); J->WriteValue(TEXT("saved"),Saved); J->WriteValue(TEXT("scope"),TEXT("Single native operation/reroute/comment export-import duplication, fresh node GUID and unlinked pins. Export intermediate allocation uncapped. Shared graphs share duplicates. No clipboard interaction, explicit compile request/wait, simulation or rendering.")); J->WriteObjectEnd(); J->Close(); return Result;
}

