FString NiagaraUtils::RenameScriptInput(const FNiagaraReq& R)
{
 if(!IsInGameThread() || !GEditor || GEditor->PlayWorld || !R.bConfirm || !R.AssetPath.StartsWith(TEXT("/Game/")) || R.AssetPath.IsEmpty() || R.AssetPath.Len()>1024 || R.AssetPath.Contains(TEXT(":")) || !FPackageName::IsValidObjectPath(R.AssetPath) || !FModuleManager::LoadModuleChecked<FAssetRegistryModule>(TEXT("AssetRegistry")).Get().GetAssetByObjectPath(FSoftObjectPath(R.AssetPath)).IsValid()) throw std::runtime_error("Registered bounded script asset path required");
 FGuid Version; if(R.VersionId.Len()>64 || !FGuid::Parse(R.VersionId,Version) || !Version.IsValid()) throw std::runtime_error("Explicit valid script version required");
 auto* Script=LoadObject<UNiagaraScript>(nullptr,*R.AssetPath); if(!IsValid(Script) || Script->HasAnyFlags(RF_Transient) || !ExactScriptData(Script,Version)) throw std::runtime_error("Persistent script and existing version required");
 auto* Source=Cast<UNiagaraScriptSource>(Script->GetSource(Version)); auto* Graph=IsValid(Source)?Source->NodeGraph.Get():nullptr;
 if(!IsValid(Graph) || !Graph->IsIn(Script) || Graph->Nodes.Num()>256 || R.NodePath.IsEmpty() || R.NodePath.Len()>2048 || R.NodeId.Len()>64) throw std::runtime_error("Owned bounded script graph/node identity and bounded coordinates required");
 FGuid Id; if(!FGuid::Parse(R.NodeId,Id) || !Id.IsValid()) throw std::runtime_error("Valid node GUID required"); UEdGraphNode* Node=nullptr; int32 Matches=0;
 for(const auto& Item:Graph->Nodes) if(IsValid(Item.Get()) && Item->NodeGuid==Id) { ++Matches; Node=Item.Get(); }
 if(Matches!=1 || !Node || Node->GetPathName()!=R.NodePath || Node->GetGraph()!=Graph) throw std::runtime_error("Unique current node GUID/path/graph identity required");
 auto* Input=Cast<UNiagaraNodeInput>(Node); if(!Input || Input->Usage!=ENiagaraInputNodeUsage::Parameter || R.NewName.IsEmpty() || R.NewName.Len()>128 || FNiagaraUtilities::SanitizeNameForObjectsAndPackages(R.NewName)!=R.NewName || FName(*R.NewName).IsNone()) throw std::runtime_error("Parameter input and native-safe bounded new name required");
 const FName Before=Input->Input.GetName(),Requested(*R.NewName); TArray<UNiagaraNodeInput*> Affected;
 for(const auto& Item:Graph->Nodes) if(auto* Candidate=Cast<UNiagaraNodeInput>(Item.Get())) { if(Candidate->Usage==Input->Usage && Candidate->Input.GetName()==Before) { if(Candidate->Pins.Num()>64) throw std::runtime_error("Affected input pins exceed bound"); Affected.Add(Candidate); } else if(Candidate->Input.GetName()==Requested) throw std::runtime_error("Input name collision"); }
 const bool Changed=!Before.IsEqual(Requested,ENameCase::CaseSensitive,false); bool Saved=false;
 if(!R.bDryRun && Changed)
 {
  FScopedTransaction Transaction(FText::FromString(TEXT("MCP Niagara Rename Input"))); Script->Modify(); Source->Modify(); Graph->Modify(); Node->SetFlags(RF_Transactional); Node->Modify(); for(auto* Candidate:Affected) Candidate->Modify(); Node->OnRenameNode(R.NewName); Graph->NotifyGraphChanged();
  const auto* Current=Cast<UNiagaraScriptSource>(Script->GetSource(Version)); if(!IsValid(Current) || Current->NodeGraph.Get()!=Graph || !Graph->Nodes.Contains(Node) || Node->NodeGuid!=Id || Node->GetPathName()!=R.NodePath || !Input->Input.GetName().IsEqual(Requested,ENameCase::CaseSensitive,false)) throw std::runtime_error("Input rename readback mismatch; inspect undo transaction"); for(const auto* Candidate:Affected) if(!Graph->Nodes.Contains(Candidate) || !Candidate->Input.GetName().IsEqual(Requested,ENameCase::CaseSensitive,false)) throw std::runtime_error("Affected input rename mismatch; inspect undo transaction"); Script->MarkPackageDirty();
 }
 if(!R.bDryRun && R.bSave) { Saved=GEditor->GetEditorSubsystem<UEditorAssetSubsystem>()->SaveLoadedAsset(Script,false); if(!Saved) throw std::runtime_error("Input renamed but script save failed"); }
 FString Result; auto J=TJsonWriterFactory<>::Create(&Result); J->WriteObjectStart(); J->WriteValue(TEXT("asset_path"),R.AssetPath); J->WriteValue(TEXT("version_id"),R.VersionId); J->WriteValue(TEXT("node_id"),R.NodeId); J->WriteValue(TEXT("node_path"),R.NodePath); J->WriteValue(TEXT("before_name"),Before.ToString()); J->WriteValue(TEXT("requested_name"),Requested.ToString()); J->WriteValue(TEXT("affected_inputs"),Affected.Num()); J->WriteValue(TEXT("would_change"),Changed); J->WriteValue(TEXT("dry_run"),R.bDryRun); J->WriteValue(TEXT("saved"),Saved); J->WriteValue(TEXT("scope"),TEXT("Native input rename synchronizes same-name/same-usage input nodes and reallocates pins; external callers are not migrated. Shared graph versions share rename. Native callbacks may schedule derived work. No explicit compile request/wait, simulation or rendering.")); J->WriteObjectEnd(); J->Close(); return Result;
}

