 if(R.ParameterName.IsEmpty() || R.ParameterName.Len()>128 || FNiagaraUtilities::SanitizeNameForObjectsAndPackages(R.ParameterName)!=R.ParameterName || FName(*R.ParameterName).IsNone()) throw std::runtime_error("Bounded native-safe output name required"); const FName Name(*R.ParameterName); for(const auto& Item:Output->GetOutputs()) if(Item.GetName()==Name) throw std::runtime_error("Output name already exists");
