 FGuid Id; if(!FGuid::Parse(R.EmitterId,Id) || !Id.IsValid()) throw std::runtime_error("Valid expected emitter GUID required");
 if(!FModuleManager::LoadModuleChecked<FAssetRegistryModule>(TEXT("AssetRegistry")).Get().GetAssetByObjectPath(FSoftObjectPath(R.AssetPath)).IsValid()) throw std::runtime_error("Registered system required");
 auto* System=LoadObject<UNiagaraSystem>(nullptr,*R.AssetPath);
 if(!IsValid(System) || System->HasAnyFlags(RF_Transient) || System->GetEmitterHandles().Num()>128 || !System->GetEmitterHandles().IsValidIndex(R.EmitterIndex) || System->GetEmitterHandles()[R.EmitterIndex].GetId()!=Id) throw std::runtime_error("Persistent bounded system/current emitter identity required");
 const auto Instance=System->GetEmitterHandles()[R.EmitterIndex].GetInstance(); auto* Data=Instance.GetEmitterData(); FGuid Version;
 if(R.VersionId.Len()>64 || !FGuid::Parse(R.VersionId,Version) || Version!=Instance.Version || !Data || !IsValid(Instance.Emitter) || !Instance.Emitter->IsIn(System)) throw std::runtime_error("Owned stateful emitter and exact current version GUID required");
 ENiagaraScriptUsage Usage;
 if(R.ValueKind==TEXT("particle_spawn")) Usage=ENiagaraScriptUsage::ParticleSpawnScript; else if(R.ValueKind==TEXT("particle_update")) Usage=ENiagaraScriptUsage::ParticleUpdateScript; else if(R.ValueKind==TEXT("emitter_spawn")) Usage=ENiagaraScriptUsage::EmitterSpawnScript; else if(R.ValueKind==TEXT("emitter_update")) Usage=ENiagaraScriptUsage::EmitterUpdateScript; else throw std::runtime_error("Supported emitter stack usage required");
 auto* Source=Cast<UNiagaraScriptSource>(Data->GraphSource.Get()); auto* Graph=IsValid(Source)?Source->NodeGraph.Get():nullptr; if(!IsValid(Graph) || !Graph->IsIn(Instance.Emitter) || Graph->Nodes.Num()>256) throw std::runtime_error("Owned emitter graph with capacity required");
 UNiagaraNodeOutput* Output=nullptr; int32 OutputMatches=0; for(const auto& Item:Graph->Nodes) if(auto* Candidate=Cast<UNiagaraNodeOutput>(Item.Get())) if(Candidate->GetUsage()==Usage || (Usage==ENiagaraScriptUsage::ParticleSpawnScript && Candidate->GetUsage()==ENiagaraScriptUsage::ParticleSpawnScriptInterpolated)) { Output=Candidate; ++OutputMatches; } if(OutputMatches!=1 || !Output) throw std::runtime_error("Unique native stack output required");
 TArray<UNiagaraNodeFunctionCall*> Modules; TSet<const UEdGraphNode*> Visited; const UEdGraphNode* Current=Output; FString Stop=TEXT("end");
